 update(m){this.clear();this.pick=[];if(this.t.type==='x-net'){if(!this.fitInitialized||this.previousFold===0&&m.fold>0||this.previousFold>0&&m.fold===0){const offset=this.camera.position.clone().sub(this.controls.target).normalize();this.camera.position.copy(this.controls.target.clone().add(offset.multiplyScalar(m.fold>0?3.8:9)));this.fitInitialized=true;}this.previousFold=m.fold;}if(this.t.type==='x-solid'){const s=solid(this.t.shape);s.faces.forEach((face,i)=>{const positions=[];for(let j=1;j<face.length-1;j++)for(const k of [face[0],face[j],face[j+1]])positions.push(...s.vertices[k]);const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));geo.computeVertexNormals();const mesh=new THREE.Mesh(geo,this.material(m.marks.faces.includes(i)?0xe0b347:colors[i%6]));mesh.userData.index=i;this.group.add(mesh);if(m.mode==='faces')this.pick.push(mesh);});s.edges.forEach(([i,j],k)=>{const a=V(s.vertices[i]),b=V(s.vertices[j]),mesh=new THREE.Mesh(new THREE.CylinderGeometry(m.mode==='edges'?.055:.018,m.mode==='edges'?.055:.018,a.distanceTo(b),8),this.material(m.marks.edges.includes(k)?0xe0b347:0x334f48));mesh.position.copy(a.clone().add(b).multiplyScalar(.5));mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),b.clone().sub(a).normalize());mesh.userData.index=k;this.group.add(mesh);if(m.mode==='edges')this.pick.push(mesh);});s.vertices.forEach((p,i)=>{const mesh=new THREE.Mesh(new THREE.SphereGeometry(m.mode==='vertices'?.1:.025,12,10),this.material(m.marks.vertices.includes(i)?0xe0b347:0x334f48));mesh.position.fromArray(p);mesh.userData.index=i;this.group.add(mesh);if(m.mode==='vertices')this.pick.push(mesh);});}
 else{const f=foldedNet(m.cells),groups=m.cells.map((_,i)=>{const g=new THREE.Group(),canvas=document.createElement('canvas');canvas.width=canvas.height=128;const ctx=canvas.getContext('2d');ctx.fillStyle='#'+colors[i%6].toString(16).padStart(6,'0');ctx.fillRect(0,0,128,128);ctx.fillStyle='#294b43';ctx.font='bold 58px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String.fromCharCode(65+i),64,66);const texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;const face=new THREE.Mesh(new THREE.PlaneGeometry(.98,.98),new THREE.MeshBasicMaterial({map:texture,side:THREE.DoubleSide}));g.add(face);const edge=new THREE.LineSegments(new THREE.EdgesGeometry(face.geometry),new THREE.LineBasicMaterial({color:0x334f48}));g.add(edge);return g;});if(groups[0])this.group.add(groups[0]);for(const{parent,child,dx,dy}of f.tree){const hinge=new THREE.Group();hinge.position.set(dx*.5,-dy*.5,0);groups[parent].add(hinge);groups[child].position.set(dx*.5,-dy*.5,0);hinge.add(groups[child]);if(dx)hinge.rotation.y=dx*m.fold/100*Math.PI/2;else hinge.rotation.x=dy*m.fold/100*Math.PI/2;}const connected=new Set([0,...f.tree.map(t=>t.child)]);groups.forEach((g,i)=>{if(!connected.has(i)){g.position.set(m.cells[i][0]-m.cells[0][0],-m.cells[i][1]+m.cells[0][1],0);this.group.add(g);}});this.group.position.set(0,0,0);this.group.updateMatrixWorld(true);if(groups.length){const center=new THREE.Box3().setFromObject(this.group).getCenter(new THREE.Vector3());this.group.position.sub(center);}}
 this.render();}
 turn(){const offset=this.camera.position.clone().sub(this.controls.target);offset.applyAxisAngle(new THREE.Vector3(0,1,0),Math.PI/4);this.camera.position.copy(this.controls.target.clone().add(offset));this.controls.update();this.render();}
